import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;

// The ViewModel holds state and a list of listeners that act as data-binding targets
class CounterViewModel {
    private int count = 0; // hidden state the ViewModel owns
    private final List<Consumer<Integer>> listeners = new ArrayList<>(); // registered bindings

    // A View calls this once to bind itself to the ViewModel
    public void addListener(Consumer<Integer> listener) {
        listeners.add(listener);
        listener.accept(count); // push the current value immediately on binding
    }

    public void increment() {
        count++; // only the ViewModel ever changes its own state
        notifyListeners(); // tell every bound listener the state changed
    }

    public void decrement() {
        count--;
        notifyListeners();
    }

    private void notifyListeners() {
        for (Consumer<Integer> listener : listeners) {
            listener.accept(count); // each bound View re-renders itself
        }
    }
}

// The View never calls itself, it only reacts when notified
class CounterView {
    private final String name;

    public CounterView(String name) {
        this.name = name;
    }

    public void render(int count) {
        System.out.println(name + " display now shows: " + count);
    }
}

public class Main {
    public static void main(String[] args) {
        CounterViewModel viewModel = new CounterViewModel(); // one shared source of truth
        CounterView screenView = new CounterView("Main screen");
        CounterView widgetView = new CounterView("Home screen widget");

        // Both views bind to the same ViewModel, nobody pushes updates manually
        viewModel.addListener(screenView::render);
        viewModel.addListener(widgetView::render);

        viewModel.increment(); // both views react automatically
        viewModel.increment();
        viewModel.decrement();
    }
}

