class CounterViewModel:
    """Holds state and a list of listeners that act as data bindings."""

    def __init__(self):
        self._count = 0  # hidden state the ViewModel owns
        self._listeners = []  # registered bindings

    def add_listener(self, listener):
        # A View calls this once to bind itself to the ViewModel
        self._listeners.append(listener)
        listener(self._count)  # push the current value immediately on binding

    def increment(self):
        self._count += 1  # only the ViewModel ever changes its own state
        self._notify_listeners()  # tell every bound listener the state changed

    def decrement(self):
        self._count -= 1
        self._notify_listeners()

    def _notify_listeners(self):
        for listener in self._listeners:
            listener(self._count)  # each bound View re-renders itself


