#include <iostream>
#include <vector>
#include <functional>
#include <string>

using namespace std;

// The ViewModel holds state and a list of listeners that act as data-binding targets
class CounterViewModel {
private:
    int count = 0; // hidden state the ViewModel owns
    vector<function<void(int)>> listeners; // registered bindings

    void notifyListeners() {
        for (auto& listener : listeners) {
            listener(count); // each bound View re-renders itself
        }
    }

public:
    // A View calls this once to bind itself to the ViewModel
    void addListener(function<void(int)> listener) {
        listeners.push_back(listener);
        listener(count); // push the current value immediately on binding
    }

    void increment() {
        count++; // only the ViewModel ever changes its own state
        notifyListeners(); // tell every bound listener the state changed
    }

    void decrement() {
        count--;
        notifyListeners();
    }
};

// The View never calls itself, it only reacts when notified
class CounterView {
private:
    string name;

public:
    CounterView(string viewName) : name(viewName) {}

    void render(int count) {
        cout << name << " display now shows: " << count << endl;
    }
};

int main() {
    CounterViewModel viewModel; // one shared source of truth
    CounterView screenView("Main screen");
    CounterView widgetView("Home screen widget");

    // Both views bind to the same ViewModel, nobody pushes updates manually
    viewModel.addListener([&screenView](int count) { screenView.render(count); });
    viewModel.addListener([&widgetView](int count) { widgetView.render(count); });

    viewModel.increment(); // both views react automatically
    viewModel.increment();
    viewModel.decrement();

    return 0;
}
